create extension if not exists "pgcrypto";
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,base_currency text not null default 'USD',timezone text not null default 'Asia/Kuala_Lumpur',created_at timestamptz not null default now());
create table if not exists public.trading_accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,account_type text not null default 'personal',starting_balance numeric(18,2) not null default 0,current_balance numeric(18,2),currency text not null default 'USD',max_daily_loss numeric(18,2),max_drawdown numeric(18,2),created_at timestamptz not null default now());
create table if not exists public.strategies(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,description text,rules text,created_at timestamptz not null default now());
create table if not exists public.trades(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id uuid references public.trading_accounts(id) on delete set null,strategy_id uuid references public.strategies(id) on delete set null,symbol text not null,asset_class text,direction text not null check(direction in ('long','short')),entry_at timestamptz not null,exit_at timestamptz,entry_price numeric(28,10),exit_price numeric(28,10),position_size numeric(28,10),stop_loss numeric(28,10),take_profit numeric(28,10),gross_pnl numeric(18,2) not null default 0,commission numeric(18,2) not null default 0,swap numeric(18,2) not null default 0,fees numeric(18,2) not null default 0,net_pnl numeric(18,2) generated always as(gross_pnl-commission-swap-fees) stored,risk_amount numeric(18,2),risk_percent numeric(9,4),r_multiple numeric(12,4),session text,emotion text,mistake text,setup_quality smallint check(setup_quality between 1 and 10),execution_quality smallint check(execution_quality between 1 and 10),discipline smallint check(discipline between 1 and 10),mae numeric(18,6),mfe numeric(18,6),notes text,created_at timestamptz not null default now());
create table if not exists public.tags(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,category text,created_at timestamptz not null default now(),unique(user_id,name));
create table if not exists public.trade_tags(trade_id uuid not null references public.trades(id) on delete cascade,tag_id uuid not null references public.tags(id) on delete cascade,primary key(trade_id,tag_id));
create table if not exists public.trade_screenshots(id uuid primary key default gen_random_uuid(),trade_id uuid not null references public.trades(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,storage_path text not null,kind text not null default 'after',caption text,created_at timestamptz not null default now());
create table if not exists public.daily_reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,review_date date not null,plan_followed boolean,execution_score smallint check(execution_score between 1 and 10),mood_score smallint check(mood_score between 1 and 10),what_went_well text,mistakes text,tomorrow_plan text,created_at timestamptz not null default now(),unique(user_id,review_date));
create table if not exists public.weekly_reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,week_start date not null,summary text,lessons text,action_plan text,created_at timestamptz not null default now(),unique(user_id,week_start));
-- Phase 7 (Bursa Malaysia stock trading): broker per account and the stored fee breakdown.
alter table public.trading_accounts add column if not exists broker text;
alter table public.trades add column if not exists fee_breakdown jsonb;
create index if not exists trades_user_entry_idx on public.trades(user_id,entry_at desc);create index if not exists trades_user_symbol_idx on public.trades(user_id,symbol);create index if not exists trades_account_idx on public.trades(account_id);create index if not exists screenshots_trade_idx on public.trade_screenshots(trade_id);
alter table public.profiles enable row level security;alter table public.trading_accounts enable row level security;alter table public.strategies enable row level security;alter table public.trades enable row level security;alter table public.tags enable row level security;alter table public.trade_tags enable row level security;alter table public.trade_screenshots enable row level security;alter table public.daily_reviews enable row level security;alter table public.weekly_reviews enable row level security;
drop policy if exists "profiles own" on public.profiles;drop policy if exists "accounts own" on public.trading_accounts;drop policy if exists "strategies own" on public.strategies;drop policy if exists "trades own" on public.trades;drop policy if exists "tags own" on public.tags;drop policy if exists "screenshots own" on public.trade_screenshots;drop policy if exists "daily reviews own" on public.daily_reviews;drop policy if exists "weekly reviews own" on public.weekly_reviews;drop policy if exists "trade tags via own trade" on public.trade_tags;drop policy if exists "trade tags own tag" on public.trade_tags;drop policy if exists "trade tags own rows" on public.trade_tags;
create policy "profiles own" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);create policy "accounts own" on public.trading_accounts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "strategies own" on public.strategies for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "trades own" on public.trades for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "tags own" on public.tags for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "screenshots own" on public.trade_screenshots for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "daily reviews own" on public.daily_reviews for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "weekly reviews own" on public.weekly_reviews for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "trade tags own rows" on public.trade_tags for all using(exists(select 1 from public.trades t where t.id=trade_id and t.user_id=auth.uid()) and exists(select 1 from public.tags x where x.id=tag_id and x.user_id=auth.uid())) with check(exists(select 1 from public.trades t where t.id=trade_id and t.user_id=auth.uid()) and exists(select 1 from public.tags x where x.id=tag_id and x.user_id=auth.uid()));
-- Phase 9 (IPO allocations and the Zakat page).
-- `is_ipo` marks a position that came from an IPO allotment rather than a market buy.
alter table public.trades add column if not exists is_ipo boolean not null default false;
-- One row per year: the rate (default 2.5%), what it is applied to, and any manual adjustment.
create table if not exists public.zakat_years(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,year int not null,rate numeric(6,3) not null default 2.5,basis text not null default 'net',other_income numeric(18,2) not null default 0,manual_base numeric(18,2),nisab numeric(18,2),created_at timestamptz not null default now(),unique(user_id,year));
create table if not exists public.zakat_payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,year int not null,paid_on date not null default current_date,amount numeric(18,2) not null default 0,method text,note text,created_at timestamptz not null default now());
create index if not exists zakat_payments_user_year_idx on public.zakat_payments(user_id,year);
alter table public.zakat_years enable row level security;alter table public.zakat_payments enable row level security;
drop policy if exists "zakat years own" on public.zakat_years;drop policy if exists "zakat payments own" on public.zakat_payments;
create policy "zakat years own" on public.zakat_years for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "zakat payments own" on public.zakat_payments for all using(auth.uid()=user_id) with check(auth.uid()=user_id);

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,display_name) values(new.id,new.raw_user_meta_data->>'display_name') on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

-- PRIVATE Storage bucket: create it if it does not exist yet (idempotent).
insert into storage.buckets(id,name,public) values('trade-screenshots','trade-screenshots',false) on conflict(id) do update set public=false;
-- Storage policies (authenticated users only, scoped to their user-id folder):
drop policy if exists "screenshots insert own folder" on storage.objects;drop policy if exists "screenshots read own folder" on storage.objects;drop policy if exists "screenshots delete own folder" on storage.objects;
create policy "screenshots insert own folder" on storage.objects for insert to authenticated with check(bucket_id='trade-screenshots' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "screenshots read own folder" on storage.objects for select to authenticated using(bucket_id='trade-screenshots' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "screenshots delete own folder" on storage.objects for delete to authenticated using(bucket_id='trade-screenshots' and (storage.foldername(name))[1]=auth.uid()::text);
